-- ANGELCARE Footer Studio 2026 / Additional professional theme architectures
-- Forward-only and idempotent: does not alter existing 8 themes or published profiles.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('angelcare:footer-studio:2026:theme-expansion'));
DO $$ BEGIN IF to_regclass('public.angelcare_marketplace_footer_themes') IS NULL THEN RAISE EXCEPTION 'Footer Studio themes table missing; apply the original Footer Command Studio migration first.'; END IF; END $$;
ON CONFLICT (theme_key) DO NOTHING;
DO $$ DECLARE n integer; BEGIN SELECT count(*) INTO n FROM public.angelcare_marketplace_footer_themes WHERE theme_key = ANY(ARRAY['editorial-atrium','architect-monolith','atelier-bento','signal-spectrum','terrace-mediterranean','institutional-ledger','calm-canopy','orbit-capsule','civic-index','chromatic-ribbon']::text[]); IF n<>10 THEN RAISE EXCEPTION 'Expected 10 registered premium footer themes; got %',n; END IF; END $$;
COMMIT;